-- Шаг 71: PageSpeed страницы «Удаление тату» (шаблон «Категория NEW», 19: 625 / 321 / 1625) — 7 старых файлов стилей (reset / template /
-- blog / fonts / media / slimmenu и study.css, ~68 КБ gzip, блокируют отрисовку) заменены двумя сокращёнными: tz-legacy.css (до redesign.css)
-- и tz-study.css (после) — их подключает lb-head. Здесь: из чанка head убран блок со старыми файлами для шаблона 19, из шаблона 19 — study.css.
-- Повторный запуск ничего не меняет.
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '    {* старые стили — только «Категория NEW» (19, старые блоки); на страницах нового дизайна — legacy.css из lb-head (шаг 66) *}\n    {if $_modx->resource.template == 19}\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/reset.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/reset.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	<link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/template.css?ver=1.0.2\"/>\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/blog.css?ver=17.02.2403\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/blog.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/fonts.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/fonts.css\"/> -->\n	\n	<link rel=\"stylesheet\" href=\"/assets/templates/css/media.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/media.css\"/> -->\n    \n    <link rel=\"stylesheet\" href=\"/assets/templates/css/slimmenu.css\"/>\n	<!-- <link rel=\"preload\" as=\"style\" href=\"/assets/templates/css/slimmenu.css\"/> -->\n    {/if}\n', '    {* старые стили «Категория NEW» (19) — tz-legacy.css / tz-study.css из lb-head (шаг 71), на страницах нового дизайна — legacy.css (шаг 66) *}\n') WHERE name = 'head';
UPDATE Impulse_Digital_X_site_templates SET content = REPLACE(content, '    <link rel=\"stylesheet\" href=\"/assets/templates/css/study.css\">\n', '') WHERE id = 19;

